insert into public.procedures(code,name,surface_type,contamination,risk_level,steps,stop_conditions,verified,version,pass_plan,drying_rule,mechanical_method,chemical_rule,source_note)
values
('textile-light','Текстиль — лёгкое загрязнение','textile','light','low',
 '["Зафиксировать исходные повреждения и тщательно убрать сухую грязь пылесосом до увлажнения.","Определить материал и сделать spot-test на перенос цвета и изменение фактуры.","Нанести минимально необходимое количество подтверждённого средства, соблюдая выдержку производителя.","Аккуратно проработать материал и выполнить экстракцию до максимально возможного удаления раствора.","Оценить результат: при лёгком загрязнении нормой является один полноценный цикл."]'::jsonb,
 '["При тесте переносится цвет.","Меняется оттенок, фактура, швы или подложка.","Наполнитель остаётся сильно переувлажнённым после экстракции.","Материал неизвестный или ранее реагировал на химию."]'::jsonb,true,1,
 '1 полноценный щадящий цикл. Второй проход — только локально после экстракции и оценки.',
 'Полное высыхание перед небольшим локальным повтором устойчивого текстиля не требуется, если предыдущий раствор хорошо извлечён и материал не переувлажнён. Перед использованием изделие должно нормально высохнуть.',
 'Сначала пылесос. Мягкая/средняя щётка только после теста; без чрезмерного трения.',
 'Только manufacturer_verified средство SIR, явно подходящее для текстиля. Начинать с наименее агрессивной эффективной концентрации в диапазоне производителя. Не смешивать средства без прямого разрешения производителя.',
 'Внутренняя консервативная процедура SIR; конкретные разведение и выдержка берутся из подтверждённой карточки средства.'),
('textile-medium','Текстиль — среднее загрязнение','textile','medium','caution',
 '["Зафиксировать повреждения и максимально удалить сухую грязь.","Определить материал и протестировать химию и механическое воздействие.","Предварительно обработать загрязнённые зоны подтверждённым средством; не давать средству высыхать, если это запрещено производителем.","Выполнить основной цикл и хорошую экстракцию.","Осмотреть при хорошем свете и повторять только оставшиеся проблемные зоны, а не всё изделие автоматически.","После финальной экстракции организовать вентиляцию и сушку."]'::jsonb,
 '["Перенос цвета, липкость, белёсость или изменение фактуры.","Поролон/подложка остаётся насыщенной водой.","Неизвестное пятно реагирует непредсказуемо.","После увлажнения усиливается подозрительный запах или есть признаки биологического загрязнения."]'::jsonb,true,1,
 'Предобработка + 1 основной экстракционный цикл + локальный повтор по необходимости.',
 'На устойчивом текстиле локальный повтор допустим сразу после хорошей экстракции. Если материал насыщен влагой, появляется обратный выход пятна или есть сомнение в стабильности — дать зоне стабилизироваться/частично подсохнуть.',
 'Пылесос до химии; контролируемая работа щёткой. Не компенсировать неправильно выбранную химию чрезмерным трением.',
 'Только подтверждённая химия для текстиля. Перед сменой средства максимально удалить предыдущий раствор; неизвестные продукты не наслаивать.',
 'Внутренняя консервативная процедура SIR; разведение и выдержка — только из manufacturer_verified карточки.'),
('textile-heavy','Текстиль — сильное загрязнение','textile','heavy','caution',
 '["Сфотографировать и классифицировать пятна до увлажнения.","Глубоко убрать сухую грязь; локальные пятна отделить от общей мойки.","Каждый более сильный этап сначала протестировать на незаметной зоне.","Работать этапами: предобработка → экстракция → оценка → решение о следующем локальном этапе.","Перед сменой средства или концентрации удалить предыдущий раствор.","Если безопасный прогресс остановился — зафиксировать ограничение, а не усиливать воздействие бесконечно."]'::jsonb,
 '["Повторные проходы только увеличивают влажность без заметного улучшения.","Меняется цвет/фактура или ослабевают волокна.","Есть риск для клея, подложки, поролона или электроники.","Плесень, биологические загрязнения или неизвестный опасный остаток без отдельного протокола/PPE."]'::jsonb,true,1,
 'Многоэтапно. Каждый этап заканчивается экстракцией и оценкой; фиксированного автоматического числа полных проходов нет.',
 'Не делать несколько мокрых проходов подряд с накоплением воды. При росте влажности, обратном выходе пятна или сомнении — стабилизация/частичная сушка. Перед использованием — полноценная сушка.',
 'Самый щадящий эффективный инструмент. Не переходить к агрессивному трению ради результата любой ценой.',
 'Только проверенная химия; менять за один раз только один фактор. Более сильная концентрация не является автоматическим следующим шагом.',
 'Внутренняя консервативная процедура SIR.'),
('carpet-light','Ковролин/пол — лёгкое','carpet','light','low',
 '["Тщательно пропылесосить, включая щели и направление ворса.","Проверить окраску и скрытые края ковролина.","Нанести небольшое количество подходящего средства и выполнить один основной цикл.","Экстрагировать до минимальной остаточной влажности и обеспечить вентиляцию."]'::jsonb,
 '["Краситель переносится.","Вода уходит под ковролин/в шумоизоляцию быстрее, чем извлекается.","Появляется стойкий запах сырости или неизвестное загрязнение."]'::jsonb,true,1,
 '1 основной цикл; локальный повтор только после оценки.',
 'Полное высыхание между локальными проходами обычно не требуется при хорошей экстракции, но нельзя допускать накопления воды в подложке. Перед выдачей автомобиль должен нормально просушиваться.',
 'Пылесос, затем щётка подходящей жёсткости без повреждения ворса; экстрактор.',
 'Manufacturer_verified средство для текстиля/ковров. При работе экстрактором учитывать рекомендацию производителя о пеногасителе. Не наслаивать неизвестную химию.',
 'SIR: отдельная процедура для ковролина и пола.'),
('carpet-medium','Ковролин/пол — среднее','carpet','medium','caution',
 '["Максимально убрать песок и сухую грязь до химии.","Spot-test на цветостойкость.","Предобработать наиболее грязные зоны и дать только разрешённую выдержку.","Проработать ворс и выполнить основной экстракционный цикл.","Повторить только участки с остаточным загрязнением после удаления первого раствора."]'::jsonb,
 '["Подложка заметно насыщается водой.","Цвет переносится или ворс повреждается.","После увлажнения появляется биологический/плесневый запах."]'::jsonb,true,1,
 'Предобработка + основной цикл + локальный повтор.',
 'Второй локальный проход возможен без полного высыхания после хорошей экстракции. Если влага накапливается в подложке — остановиться и частично просушить.',
 'Щётка по типу ворса, без чрезмерного давления; экстракция после каждого влажного этапа.',
 'Только подтверждённое средство для текстиля/ковров. Предыдущий раствор удалить перед сменой химии.',
 'SIR: отдельная процедура для ковролина и пола.'),
('carpet-heavy','Ковролин/пол — сильное','carpet','heavy','caution',
 '["Сухая очистка и пылесос до максимально возможного результата.","Локально определить типы пятен и сделать тест.","Работать небольшими зонами: предобработка → механика → экстракция → оценка.","Не заливать весь пол повторно из-за нескольких оставшихся пятен.","При выходе грязи из глубины сначала удалить влагу и дать зоне стабилизироваться."]'::jsonb,
 '["Подложка/шумоизоляция насыщена водой.","Запах усиливается после намокания.","Есть плесень/биологическое загрязнение без отдельного решения.","После нескольких безопасных этапов улучшение прекратилось."]'::jsonb,true,1,
 'Многоэтапная локальная работа; после каждого этапа обязательна экстракция. Число полных проходов заранее не фиксируется.',
 'При накоплении влаги нужна пауза и частичная сушка. Перед эксплуатацией салон должен быть достаточно сухим, чтобы не создавать запах/плесень.',
 'Контролируемая щётка по ворсу + экстрактор. Не повреждать края, крепёж и проводку под ковролином.',
 'Подтверждённая химия для текстиля/ковров. Усиление только после теста и удаления предыдущего раствора.',
 'SIR: отдельная процедура для сильного ковролина.'),
('headliner-light','Потолок — лёгкое загрязнение','headliner','light','caution',
 '["Осмотреть провисание, края, старые ремонты и стабильность цвета.","Сделать тест на незаметном участке.","Работать небольшими зонами с минимальным увлажнением.","Удалять поверхностную грязь, не насыщая подложку и клей.","После первого прохода оценить материал; не догонять небольшое пятно повторным намоканием без необходимости."]'::jsonb,
 '["Любое провисание, размягчение, пузырение или отход края.","Перенос цвета/изменение оттенка.","Неизвестное состояние клея или следы ремонта потолка."]'::jsonb,true,1,
 'Обычно 1 контролируемый маловлажный проход. Повтор — небольшой и локальный.',
 'Перед локальным повтором зона должна быть стабильной, без размягчения/провисания. При сомнении в клее дать ей частично подсохнуть.',
 'Мягкая микрофибра/очень мягкая щётка. Без жёсткого трения и без промывки потолка как ковролина.',
 'Только средство с подтверждённой совместимостью с материалом потолка/текстилем, в минимальном количестве. Подложку не насыщать.',
 'SIR: повышенная осторожность — состояние клея по фото не определяется.'),
('headliner-medium','Потолок — среднее загрязнение','headliner','medium','high_risk',
 '["Сфотографировать весь потолок, особенно края и уже провисающие зоны.","Протестировать химию и очень мягкое механическое воздействие.","Работать малыми зонами с контролируемой влагой.","Закончить одну зону, удалить остатки/влагу и проверить стабильность перед следующей.","Второй локальный этап допускается только если первый не повлиял на клей/фактуру и ожидаемая польза выше риска."]'::jsonb,
 '["Провисание, размягчение клея, пузырение или движение края/шва.","Перенос цвета или повреждение ворса.","Для косметического идеала требуется повторное сильное намокание."]'::jsonb,true,1,
 '1 контролируемый проход малыми зонами; второй — только на отдельных пятнах после проверки стабильности.',
 'Сомнительную зону повторно сразу не увлажнять: дать стабилизироваться/частично подсохнуть. Полное высыхание нужно для окончательной оценки клея.',
 'Только очень мягкое локальное воздействие. Никакой обильной экстракционной промывки.',
 'Минимальное количество manufacturer_verified совместимого средства. Не переходить на более сильную химию только потому, что осталось пятно.',
 'SIR: HIGH RISK для среднего загрязнения потолка.'),
('headliner-heavy','Потолок — сильное загрязнение','headliner','heavy','high_risk',
 '["До осмотра не обещать полное удаление загрязнений.","Проверить прочность приклейки, провисание и старые ремонты; сделать фото.","Начать с самого щадящего тестового участка.","Обрабатывать только зоны, которые очищаются без насыщения подложки.","Если результат требует повторного сильного увлажнения — STOP и решение OWNER."]'::jsonb,
 '["Есть/появляется провисание.","Размягчается клей/подложка.","Никотин/неизвестный налёт требует непроверенной химии.","Ожидание клиента требует небезопасного многократного намокания."]'::jsonb,true,1,
 'Автоматического многоэтапного плана нет. Один осторожный тестовый участок определяет, можно ли продолжать; усиление — после решения OWNER.',
 'Тестовые зоны должны стабилизироваться/подсохнуть перед усилением. Мокрые проходы подряд для HIGH RISK потолка запрещены.',
 'Минимальное воздействие, без жёсткой щётки и заливания.',
 'Только подтверждённая совместимая химия с контролем влаги. Если безопасный метод не даёт результата — зафиксировать ограничение, а не рисковать потолком.',
 'SIR: HIGH RISK потолок.'),
('mattress-light','Матрас — лёгкое','mattress','light','low',
 '["Тщательно пропылесосить поверхность и швы.","Определить материал чехла и сделать тест.","Выполнить контролируемый цикл без пропитывания внутреннего наполнителя.","Хорошо извлечь влагу и обеспечить активную вентиляцию."]'::jsonb,
 '["Перенос цвета/деформация ткани.","Наполнитель сильно насыщается водой.","Плесень, биологические жидкости или другое особое загрязнение."]'::jsonb,true,1,
 '1 контролируемый цикл; локальный повтор только при стабильном и не переувлажнённом чехле.',
 'Матрас должен полностью высохнуть перед сном/использованием. Влажный матрас клиенту как готовый не выдавать.',
 'Пылесос; только мягкое воздействие на ткань.',
 'Manufacturer_verified средство для совместимого текстиля. Не пропитывать сердцевину и не маскировать запах ароматизатором.',
 'SIR: консервативная процедура матраса.'),
('mattress-medium','Матрас — среднее','mattress','medium','caution',
 '["Глубоко пропылесосить поверхность и швы.","Классифицировать пятна и сделать тест.","Предобработать только нужные зоны, затем выполнить контролируемую экстракцию.","После экстракции оценить и повторять только оставшиеся локальные зоны.","Вентилировать до полного высыхания."]'::jsonb,
 '["Влага уходит глубже быстрее, чем извлекается.","Есть подозрение на биологическое загрязнение.","Меняется цвет/фактура."]'::jsonb,true,1,
 'Предобработка + 1 основной контролируемый цикл + локальный повтор.',
 'Локальный повтор возможен после хорошей экстракции, но перед использованием матрас должен полностью высохнуть. При насыщении сердцевины — пауза и сушка.',
 'Мягкая работа по текстилю; беречь швы и стёжку.',
 'Только manufacturer_verified химия, совместимая с чехлом; тщательно удалять остатки и не наслаивать продукты.',
 'SIR: консервативная процедура матраса.'),
('mattress-heavy','Матрас — сильное','mattress','heavy','high_risk',
 '["Сфотографировать и классифицировать пятна до увлажнения.","Решить, подходит ли загрязнение для обычной химчистки или требует отказа/особого протокола.","Работать локально и этапами, не пропитывая сердцевину.","После каждого этапа делать экстракцию и оценку.","Если безопасная полная сушка не обеспечивается — STOP."]'::jsonb,
 '["Плесень/значимое биологическое загрязнение без отдельного протокола/PPE.","Глубокое насыщение сердцевины.","Источник запаха нельзя безопасно удалить.","Материал меняется при тесте."]'::jsonb,true,1,
 'Только поэтапная локальная работа; повторные полные пропитывания запрещены.',
 'При накоплении влаги в сердцевине — сушка/стабилизация. Полное высыхание перед использованием обязательно и может занять длительное время.',
 'Контролируемое мягкое воздействие; не проталкивать жидкость в швы/наполнитель.',
 'Только проверенная химия. Не повышать концентрацию и не смешивать продукты без документированного совместимого метода.',
 'SIR: HIGH RISK матрас.'),
('plastic-light','Пластик салона — лёгкое','interior_plastic','light','low',
 '["Определить чувствительные покрытия, экраны, piano black и печатные символы.","Наносить состав на микрофибру/щётку, а не заливать кнопки и швы.","Протестировать небольшую зону, затем равномерно очистить и удалить остатки."]'::jsonb,
 '["Белёсость, липкость, изменение блеска/цвета или повреждение символов.","Жидкость попадает в переключатели/электронику."]'::jsonb,true,1,
 '1 контролируемый цикл протирки; повтор только локально.',
 'Обычно ждать полного высыхания перед второй лёгкой протиркой не нужно после удаления остатков, но поверхность не должна оставаться мокрой у электроники/швов.',
 'Микрофибра и мягкая detailing-щётка; минимальное давление на покрытия/печать.',
 'Только manufacturer_verified средство, прямо подходящее для интерьерного пластика/покрытия. Не считать внешние dressings или сильную щёлочь универсальным средством салона.',
 'SIR: консервативная процедура интерьерных поверхностей.'),
('plastic-medium','Пластик салона — среднее','interior_plastic','medium','caution',
 '["Проверить покрытия и существующие белые пятна/царапины до очистки.","Сделать spot-test.","Наносить контролируемо через микрофибру/щётку, не заливать детали.","Мягко проработать текстуру, удалить остатки, проверить цвет/блеск и повторять только локально."]'::jsonb,
 '["Белёсость, липкость, смена цвета/блеска или отслоение покрытия.","Становится заметнее старое химическое повреждение.","Электронику нельзя защитить от жидкости."]'::jsonb,true,1,
 '1 основной контролируемый цикл + локальный повтор на грязных текстурных зонах.',
 'Локальная вторая протирка возможна сразу после удаления остатков и проверки стабильности. При белёсости/липкости — не повторять, STOP.',
 'Микрофибра/мягкая щётка. Не заменять правильный состав жёстким трением.',
 'Только подтверждённое средство именно для интерьерного пластика/покрытия. Непроверенную сильную щёлочь на чувствительном пластике не применять.',
 'SIR: консервативная процедура интерьерных поверхностей.'),
('plastic-heavy','Пластик салона — сильное','interior_plastic','heavy','caution',
 '["Отделить реальную грязь от уже существующего химического повреждения.","Каждый более сильный этап тестировать.","Работать этапами с небольшим количеством средства и полным удалением остатков между этапами.","Если белёсость/пятно является повреждением покрытия — прекратить усиление и зафиксировать это."]'::jsonb,
 '["Белёсость/липкость усиливается.","Сходит покрытие или печатные символы.","Для продолжения требуется химия без подтверждённой совместимости."]'::jsonb,true,1,
 'Поэтапная локальная очистка; автоматического числа повторов нет.',
 'Перед усилением удалить остатки и дать поверхности стабилизироваться. Старое химическое повреждение нельзя трактовать как обычную грязь.',
 'Только мягкая щётка/микрофибра; защита электроники и деликатных покрытий.',
 'Только подтверждённая химия для интерьерных поверхностей. Если безопасный состав не снимает след — считать его возможным повреждением и STOP.',
 'SIR: консервативная процедура интерьерных поверхностей.'),
('leather-light','Кожа/экокожа — лёгкое','leather','light','caution',
 '["Определить: покрытая кожа, синтетическая кожа или повреждённое/непокрытое основание.","Сделать тест средства и устойчивости цвета.","Работать малой зоной специализированным средством и мягкой щёткой/салфеткой.","Удалить остатки и дать поверхности высохнуть перед совместимым уходом/защитой."]'::jsonb,
 '["Переносится цвет.","Покрытие становится липким, пятнистым, тусклым или отслаивается.","Трещины/потёртости открывают нестабильный красочный слой."]'::jsonb,true,1,
 '1 мягкий цикл; локальный повтор только после проверки покрытия.',
 'Перед уходом/защитой поверхность должна высохнуть/стабилизироваться. Повреждённое покрытие нельзя держать постоянно влажным повторной очисткой.',
 'Мягкая leather-щётка/микрофибра, низкое давление.',
 'Только специализированное manufacturer_verified средство для кожи/экокожи. Экстракционную химию текстиля не использовать как замену.',
 'SIR: консервативная процедура кожи.'),
('leather-medium','Кожа/экокожа — среднее','leather','medium','caution',
 '["Осмотреть износ покрытия, трещины, перенос красителя и старые dressings.","Протестировать специализированное средство.","Работать небольшими секциями, сразу удалять остатки и проверять покрытие.","Повторять локально только при полной стабильности покрытия.","Уход/защиту наносить только если совместимы и входят в согласованную технологию."]'::jsonb,
 '["Перенос цвета/финиша.","Поверхность становится липкой, пятнистой, слишком матовой/глянцевой.","Выявляется нестабильное повреждённое покрытие."]'::jsonb,true,1,
 '1 основной цикл малыми зонами + локальный повтор при стабильном финише.',
 'Между проходами удалить остатки; сомнительные участки дать стабилизироваться. Перед защитой — просушка.',
 'Мягкая leather-щётка/микрофибра; без абразива и экстракционного насыщения.',
 'Только специализированная проверенная химия для кожи; не переходить к щелочному текстильному очистителю.',
 'SIR: консервативная процедура кожи.'),
('leather-heavy','Кожа/экокожа — сильное','leather','heavy','high_risk',
 '["Сфотографировать износ и отделить грязь от разрушенного покрытия/краски.","Начать с самого мягкого проверенного leather-safe метода.","Работать секциями и остановить усиление при нестабильности покрытия.","Постоянное повреждение покрытия объяснить клиенту, а не пытаться стереть его как грязь."]'::jsonb,
 '["Переносится краситель/финиш или отслаивается покрытие.","Ухудшаются трещины/потёртости.","Для результата требуется химия за пределами проверенных leather-safe средств."]'::jsonb,true,1,
 'Агрессивного автоматического многоэтапного плана нет. Повтор допустим только пока покрытие стабильно.',
 'Сомнительные зоны должны высохнуть/стабилизироваться до решения о следующем проходе. Повреждённый финиш постоянно не мочить.',
 'Очень мягкая щётка/микрофибра; без абразивного усиления.',
 'Только dedicated manufacturer_verified leather chemistry. Если безопасная очистка дошла до предела — STOP и фиксация повреждения.',
 'SIR: HIGH RISK кожа.'),
('seatbelt-light','Ремень безопасности — лёгкое','seat_belt','light','caution',
 '["Осмотреть ленту на порезы, распушение, химические следы и повреждения механизма.","Защитить замок и механизм втягивания от жидкости.","Очистить ленту минимально влажным способом совместимым средством и удалить остатки.","Полностью высушить ремень в вытянутом положении до возврата в эксплуатацию."]'::jsonb,
 '["Порезы, сильное распушение или повреждение ленты.","Неизвестная химия/отбеливание уже изменили волокна.","Замок или механизм втягивания намокает/работает неправильно."]'::jsonb,true,1,
 '1 щадящий цикл. Повтор — только локально после удаления остатков.',
 'Перед использованием ремень должен полностью высохнуть. Не втягивать сильно мокрую ленту в механизм.',
 'Мягкая щётка/микрофибра без повреждения волокон; механизм не замачивать.',
 'Только средство, совместимость которого с ремнём подтверждена производителем автомобиля/ремня или отдельной проверенной инструкцией. Сильную щёлочь, растворители и отбеливатель без такого разрешения не применять.',
 'SIR: ремень — элемент безопасности, поэтому химия выбирается консервативно.'),
('seatbelt-medium','Ремень безопасности — среднее','seat_belt','medium','caution',
 '["Осмотреть состояние ленты и механизма до очистки.","Сначала удалить сухую грязь и протестировать минимально влажный состав.","Работать по небольшим участкам, не пропитывая механизм.","Удалить остатки и оценить, не изменились ли волокна/цвет.","Полностью высушить ремень вытянутым."]'::jsonb,
 '["Повреждение/распушение усиливается.","Переносится краситель или меняется жёсткость ленты.","Требуется непроверенная сильная химия."]'::jsonb,true,1,
 '1 основной щадящий цикл + локальный повтор только при стабильной ленте.',
 'Локальный повтор допустим после удаления раствора, но перед использованием ремень должен полностью высохнуть.',
 'Мягкая щётка без агрессивного трения; не заливать катушку/замок.',
 'Только подтверждённая совместимость для seat-belt webbing. Без отбеливателя, растворителя и сильной щёлочи без прямого разрешения изготовителя.',
 'SIR: ремень — элемент безопасности.'),
('seatbelt-heavy','Ремень безопасности — сильное','seat_belt','heavy','high_risk',
 '["Сначала решить, является ли лента безопасной для дальнейшей эксплуатации вообще.","Сфотографировать повреждения/сильное загрязнение.","Использовать только проверенный щадящий тестовый участок.","Если безопасный метод не решает проблему — STOP, не переходить к агрессивной химии."]'::jsonb,
 '["Есть порезы, распушение, следы химического разрушения.","Неизвестное загрязнение требует растворителя/отбеливателя/сильной щёлочи.","После очистки ремень хуже втягивается или меняется структура ленты."]'::jsonb,true,1,
 'Автоматических повторных сильных проходов нет. При недостаточном безопасном результате — STOP.',
 'Полная сушка обязательна. Сильно переувлажнённый механизм не использовать до проверки/высыхания.',
 'Только мягкая работа; никакого абразива.',
 'Только химия с подтверждённой совместимостью изготовителем. При отсутствии подтверждения — не экспериментировать.',
 'SIR: HIGH RISK элемент безопасности.'),
('childseat-light','Детское кресло — лёгкое','child_seat','light','caution',
 '["Сфотографировать сборку и бирки, чтобы после чистки всё вернуть правильно.","Проверить инструкцию конкретного кресла: какие чехлы снимаются и как можно чистить ремни.","Пылесосить сухую грязь до химии.","Чистить только разрешённые производителем части и обеспечить полную сушку перед использованием."]'::jsonb,
 '["Нет инструкции по уходу для конкретного кресла.","Ремни/пряжки повреждены или требуют химии, не разрешённой производителем.","Пена/наполнитель сильно насыщаются водой."]'::jsonb,true,1,
 '1 щадящий цикл строго по инструкции конкретного детского кресла.',
 'Чехол, наполнитель и ремни должны высохнуть в соответствии с инструкцией производителя до использования кресла.',
 'Пылесос, мягкая щётка/салфетка; разборка только в объёме, предусмотренном изготовителем.',
 'Приоритет всегда у инструкции производителя детского кресла. Не использовать универсальную автомобильную химию на harness/пряжках без прямого разрешения.',
 'SIR: детское кресло — safety-critical изделие.'),
('childseat-medium','Детское кресло — среднее','child_seat','medium','caution',
 '["Идентифицировать модель кресла и найти/проверить инструкцию ухода.","Зафиксировать сборку и состояние ремней/пряжек.","Снять и стирать/чистить чехлы только так, как разрешает изготовитель.","Ремни и пряжки обрабатывать отдельно только разрешённым способом.","Полностью высушить и правильно собрать перед передачей."]'::jsonb,
 '["Инструкция запрещает выбранный метод.","Повреждены harness/пряжка/крепления.","Нужно замачивание или химия без разрешения производителя."]'::jsonb,true,1,
 'По инструкции производителя; локальный повтор только на разрешённых элементах.',
 'Полная сушка до сборки/использования обязательна; не применять ускоренную сушку, если она запрещена изготовителем.',
 'Только разрешённая разборка и мягкая механика.',
 'Инструкция конкретного кресла выше любой общей процедуры SIR. Средство на ремни/пряжки — только если разрешено изготовителем.',
 'SIR: safety-critical изделие.'),
('childseat-heavy','Детское кресло — сильное','child_seat','heavy','high_risk',
 '["До начала определить модель и ограничения производителя.","Оценить, не делает ли загрязнение/повреждение кресло непригодным для безопасной эксплуатации.","Работать только в рамках разрешённой разборки и методов ухода.","Если для результата требуется запрещённое замачивание/химия — STOP и объяснить клиенту ограничение."]'::jsonb,
 '["Повреждены ремни, пряжка, корпус, энергопоглощающая пена или крепления.","Биологическое загрязнение нельзя удалить разрешённым способом.","Требуется химия/температура/замачивание, запрещённые производителем."]'::jsonb,true,1,
 'Нет универсального агрессивного плана. Только метод производителя; иначе STOP.',
 'Полная безопасная сушка обязательна. Сборка только после высыхания и по инструкции.',
 'Механика и разборка только разрешённые производителем.',
 'Никакой универсальной рекомендации химии для harness/пряжек. Следовать конкретной инструкции изготовителя.',
 'SIR: HIGH RISK safety-critical изделие.')
on conflict(code) do update set
 name=excluded.name,surface_type=excluded.surface_type,contamination=excluded.contamination,risk_level=excluded.risk_level,
 steps=excluded.steps,stop_conditions=excluded.stop_conditions,verified=excluded.verified,
 pass_plan=excluded.pass_plan,drying_rule=excluded.drying_rule,mechanical_method=excluded.mechanical_method,
 chemical_rule=excluded.chemical_rule,source_note=excluded.source_note,updated_at=now();
